public void process()
{
    next process();
    if (this.isPostMethod(request.parmName()))
    {
        MobPostOrderPromptOverride::FindAndExecute(this,this.getRequestDataMap(),request.parmName());
    }
}

public Map getCollectorMap(TFMDocumentTypeId _documentType, TFMDocumentContentSubject _contentType, Map _additionalValues)
{
    Map collectors = next getCollectorMap(_documentType, _contentType, _additionalValues);
    TFMDocumentTypeAttribute docTypeAttr = new TFMDocumentTypeAttribute(classStr(TFMPostAdhocRegistration), _contentType);
    DictMethod Method = TFMGetRegistrationConfiguration::getMethodFromSysAttribute(classIdGet(this),docTypeAttr);
    if (Method != null)
    {
        MobPostOrderPromptOverride::addToCollectors(collectors,classIdget(this),Method.name(),true,_additionalValues);
    }

    return collectors;
}

public void addToCollectors(Map _collectors, ClassId _orderClass, MethodName _methodName)
{
    next addToCollectors(_collectors, _orderClass, _methodName);
    MobPostOrderPromptOverride::addToCollectors(_collectors, _orderClass, _methodName);
}
